function parseProxy(url){
  url=(url||'').trim();
  if(!url) return {valid:false, error:'空输入'};
  var m=url.match(/^([a-zA-Z0-9]+):\/\/(.*)$/);
  if(!m) return {valid:false, error:'缺少 scheme://（支持 http/https/socks4/socks5）'};
  var scheme=m[1].toLowerCase(), rest=m[2];
  var defs={http:8080,https:443,socks4:1080,socks5:1080,socks5h:1080};
  if(!(scheme in defs)) return {valid:false, error:'不支持的 scheme: '+scheme};
  var auth='', hostport=rest;
  var at=rest.lastIndexOf('@');
  if(at>=0){ auth=rest.slice(0,at); hostport=rest.slice(at+1); }
  var user='', pass='';
  if(auth){ var c=auth.indexOf(':'); if(c>=0){ user=auth.slice(0,c); pass=auth.slice(c+1); } else user=auth; }
  var portStr='', host=hostport;
  var colon=hostport.lastIndexOf(':');
  if(colon>=0){ host=hostport.slice(0,colon); portStr=hostport.slice(colon+1); }
  if(!host) return {valid:false, error:'缺少主机'};
  var port=defs[scheme];
  if(portStr!==''){ port=parseInt(portStr,10); if(isNaN(port)||port<0||port>65535) return {valid:false, error:'端口非法: '+portStr}; }
  return {valid:true, scheme:scheme, host:host, port:port, username:user, password:pass, auth:!!user};
}

var EXPORTS={parseProxy:parseProxy};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ProxyForgePure = EXPORTS; }
